using UnityEngine;
using UnityEditor;

public class ForceAssignSprites
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();

        string pathDrink = "Assets/Herbal/JamuIcon.png";
        string pathSpice = "Assets/Herbal/SpiceIcon.png";

        // Force import as Sprite
        TextureImporter tiDrink = AssetImporter.GetAtPath(pathDrink) as TextureImporter;
        if (tiDrink != null) 
        {
            tiDrink.textureType = TextureImporterType.Sprite;
            tiDrink.spriteImportMode = SpriteImportMode.Single;
            tiDrink.SaveAndReimport();
        }

        TextureImporter tiSpice = AssetImporter.GetAtPath(pathSpice) as TextureImporter;
        if (tiSpice != null) 
        {
            tiSpice.textureType = TextureImporterType.Sprite;
            tiSpice.spriteImportMode = SpriteImportMode.Single;
            tiSpice.SaveAndReimport();
        }

        AssetDatabase.Refresh();

        // Load Sprites
        Sprite spDrink = AssetDatabase.LoadAssetAtPath<Sprite>(pathDrink);
        Sprite spSpice = AssetDatabase.LoadAssetAtPath<Sprite>(pathSpice);

        if (spDrink == null) return "ERROR: JamuIcon.png tidak ditemukan sebagai Sprite.";
        if (spSpice == null) return "ERROR: SpiceIcon.png tidak ditemukan sebagai Sprite.";

        // Assign to Recipes
        string[] recipeNames = { "Jamu Jahe", "Jamu Kunyit", "Jamu Kencur", "Jamu Temulawak", "Wedang Jahe", "Jamu Beras Kencur" };
        foreach (var rn in recipeNames)
        {
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>("Assets/Herbal/Recipes/" + rn + ".asset");
            if (recipe != null) 
            {
                recipe.recipeImage = spDrink;
                for (int i = 0; i < recipe.ingredients.Length; i++)
                {
                    recipe.ingredients[i].itemIcon = spSpice;
                }
                EditorUtility.SetDirty(recipe);
                sb.AppendLine($"[OK] Assigned ke Resep: {rn}");
            }
        }

        // Assign to Result Items
        foreach (var rn in recipeNames)
        {
            var item = AssetDatabase.LoadAssetAtPath<InventoryItem>("Assets/Herbal/Items/" + rn + ".asset");
            if (item != null) 
            {
                item.icon = spDrink;
                EditorUtility.SetDirty(item);
            }
        }

        // Assign to Ingredient Items
        string[] ingNames = { "Jahe", "Kunyit", "Kencur", "Temulawak", "Kayu Manis" };
        foreach (var iname in ingNames)
        {
            var item = AssetDatabase.LoadAssetAtPath<InventoryItem>("Assets/Herbal/Items/" + iname + ".asset");
            if (item != null) 
            {
                item.icon = spSpice;
                EditorUtility.SetDirty(item);
            }
        }

        AssetDatabase.SaveAssets();
        sb.AppendLine("[SUCCESS] Semua gambar berhasil dipasang!");
        return sb.ToString();
    }
}
